/**
 * Lebanese Dental Association seal, embedded as a data URI.
 * Printed documents (Prescription, Statement of Account) build their PDF
 * via html2canvas, which taints the canvas (so it can never be exported)
 * if the image came from a plain file:// src — common when this app is
 * opened by double-clicking index.html rather than through a server.
 * A data: URI has no such origin at all, so it works identically whether
 * the app is opened as a file, from a local server, or over https.
 */
window.CLINIC_SEAL_DATA_URI = "data:image/jpeg;base64,";
